                type('N');
                shot("conclusions-1080");
            });
            q.Enqueue(() =>
            {
                check(s.data.conclusions[0].claim == "N", "Conclusion text entry actually updated through UI");
            });
            q.Enqueue(() => click(130, 103));
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "P after conclusion text field");
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "", "P closes dossier");
                worldPosition = s.movement.transform.position;
                worldEye = s.eye.transform.rotation;
            });
            q.Enqueue(() => key(Key.W));
            q.Enqueue(() =>
            {
                release();
                check(Vector3.Distance(worldPosition, s.movement.transform.position) > .1f, "WASD works after UI");
                InputSystem.QueueStateEvent(mouse, new MouseState{delta = new Vector2(30, 0)});
            });
            q.Enqueue(() =>
            {
                release();
                check(Quaternion.Angle(worldEye, s.eye.transform.rotation) > .1f, "Mouse look works after UI");
            });
            q.Enqueue(() => key(Key.Escape));
            q.Enqueue(() =>
            {
                release();
                check(s.Paused && s.Modal, "Pause opens after typing and navigation");
                modalPosition = s.movement.transform.position;
                modalEye = s.eye.transform.rotation;
                InputSystem.QueueStateEvent(kb, new KeyboardState(Key.W));
                InputSystem.QueueStateEvent(mouse, new MouseState{delta = new Vector2(60, 0)});
            });
            q.Enqueue(() =>
            {
                release();
                check(Vector3.Distance(modalPosition, s.movement.transform.position) < .01f && Quaternion.Angle(modalEye, s.eye.transform.rotation) < .01f, "Pause blocks movement/look");
            });
            q.Enqueue(() => key(Key.F5));
            q.Enqueue(() =>
            {
                release();
                check(File.Exists(s.SavePath), "F5 while paused writes private profile");
            });
            q.Enqueue(() => key(Key.Escape));
            q.Enqueue(() =>
            {
                release();
                check(!s.Paused && !s.Modal, "Escape resumes");
            });
            q.Enqueue(() => key(Key.F6));
            q.Enqueue(() =>
            {
                release();
                check(!s.Paused && !s.Modal && s.movement.enabled && s.look.enabled, "Load of paused save returns to safe unpaused input state");
            });
            q.Enqueue(() => key(Key.F5));
            q.Enqueue(() =>
            {
                release();
                check(File.Exists(s.SavePath), "F5 world state");
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "Dossier before world load");
            });
            q.Enqueue(() => key(Key.F6));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "" && !s.Paused && s.movement.enabled && s.look.enabled, "F6 world clears modal/input locks");
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "P after world load");
            });
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "", "Return to world for controller E test");
                shot("world-final-1080");
            });
            double next = EditorApplication.timeSinceStartup + 2;
            EditorApplication.CallbackFunction f = null;
            Action finish = () =>
            {
                EditorApplication.update -= f;
                release();
                if (map != null)
                    map.devices = oldDevices;
                InputSystem.RemoveDevice(kb);
                InputSystem.RemoveDevice(mouse);
                JsonUtility.FromJsonOverwrite(prior, settings);
                File.WriteAllText(dir + "/suite.txt", b.ToString());
                File.WriteAllText(dir + "/live.json", JsonUtility.ToJson(s.data, true));
            };
            int step = 0;
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + .4;
                try
                {
                    if (q.Count == 0)
                    {
                        finish();
                        return;
                    }

                    q.Dequeue()();
                    File.WriteAllText(dir + "/progress.txt", "step=" + (++step) + " remaining=" + q.Count + " page=" + s.Page + "\n" + b);
                }
                catch (Exception e)
                {
                    b.AppendLine("FAIL " + e);
                    finish();
                }
            };
            EditorApplication.update += f;
            r.Log("UI suite queued: fixed; inspect eventual suite.txt, not callback registration.");
        }
    }
}

